	ID      int              `json:"id"`
	Players []string          `json:"players"`
	Moves   []interface{}     `json:"moves"`
	State   string            `json:"state"`
	Scores  map[string]int    `json:"scores"`
}

var (
	games      = make(map[int]*Game)
	nextGameID = 1
)

func main() {
	port := os.Getenv("PORT")
