package main

import (
	"encoding/json"
	"net/http"
	"os"
	"sort"
	"strconv"
	"strings"
)

type Move struct { Player string `json:"player"`; Move string `json:"move"`; Turn int `json:"turn"` }
type Game struct {
	ID int `json:"id"`; Players []string `json:"players"`
	Moves []Move `json:"moves"`; State string `json:"state"`
	Scores map[string]int `json:"scores"`
}
type Entry struct { Player string `json:"player"`; Score int `json:"score"` }

var (games = make(map[int]*Game); nextGameID = 1)

func handleRoute(w http.ResponseWriter, r *http.Request) {
	path := strings.TrimPrefix(r.URL.Path, "/game/")
	parts := strings.Split(path, "/")
	if len(parts) < 2 { return }
	gameID, _ := strconv.Atoi(parts[0]); game, ok := games[gameID]
	if !ok { w.Header().Set("Content-Type", "application/json"); w.WriteHeader(http.StatusNotFound); json.NewEncoder(w).Encode(map[string]string{"error": "Not found"}); return }
	w.Header().Set("Content-Type", "application/json")
	switch parts[1] {
	case "join":
		var b struct { Player string `json:"player"` }; json.NewDecoder(r.Body).Decode(&b)
		game.Players = append(game.Players, b.Player); game.Scores[b.Player] = 0
		json.NewEncoder(w).Encode(map[string]interface{}{"player": b.Player, "joined": true})
	case "move":
		var b struct { Player string `json:"player"`; Move string `json:"move"` }; json.NewDecoder(r.Body).Decode(&b)
		game.Moves = append(game.Moves, Move{Player: b.Player, Move: b.Move, Turn: len(game.Moves) + 1})
		game.Scores[b.Player]++
		json.NewEncoder(w).Encode(map[string]interface{}{"player": b.Player, "move": b.Move, "turn": len(game.Moves)})
	case "state":
		json.NewEncoder(w).Encode(game)
	case "leaderboard":
		entries := make([]Entry, 0)
		for _, p := range game.Players { entries = append(entries, Entry{Player: p, Score: game.Scores[p]}) }
		sort.Slice(entries, func(i, j int) bool { return entries[i].Score > entries[j].Score })
		json.NewEncoder(w).Encode(entries)
	}
}

func main() {
	port := os.Getenv("PORT")
	if port == "" { port = "3000" }

	http.HandleFunc("/game/create", func(w http.ResponseWriter, r *http.Request) {
		gameID := nextGameID; nextGameID++
		games[gameID] = &Game{ID: gameID, Players: []string{}, Moves: []Move{}, State: "waiting", Scores: map[string]int{}}
		w.Header().Set("Content-Type", "application/json"); w.WriteHeader(http.StatusCreated)
		json.NewEncoder(w).Encode(map[string]int{"gameId": gameID})
	})

	http.HandleFunc("/game/", handleRoute)
	http.ListenAndServe(":"+port, nil)
}
